    for (let i = 0; i < m; i++) {
        if (norm(da[i]) < 1e-12 || norm(db[i]) < 1e-12)
            sum += 1;
        else
            sum += 1 - cosine(da[i], db[i]);
    }
    return m === 0 ? 0 : Math.min(2, Math.max(0, sum / m));
}
